"""BAT-02 batch job runner migration."""

from typing import Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], None]) -> list[dict]:
    """Run scheduled jobs sequentially using legacy ON_ERROR semantics."""
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]

        if policy == "RETRY":
            maximum_attempts = on_error["retries"] + 1
        else:
            maximum_attempts = 1

        attempts = 0
        succeeded = False

        while attempts < maximum_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "RETRY" and attempts < maximum_attempts:
                    continue
                break
            else:
                succeeded = True
                break

        if succeeded:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )
            continue

        if policy == "CONTINUE":
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "skip",
                    "audits": ["BATCH_ROWSKIP"],
                }
            )
            continue

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "abort",
                "audits": [],
            }
        )
        break

    return run_log
